const j = $json;
const yearMap = { 'SY': 2, 'TY': 3, 'Final Year': 4 };
const branches = ['CSE','CSE-DS','CSE-AIML','Civil','Mechanical','ENTC'];
const divisions = ['A','B','C','D','E','F','G','H','I'];
const branch = String(j['Branch'] || '').trim();
const yearLabel = String(j['Year'] || '').trim();
const division = String(j['Division'] || '').trim().toUpperCase();
const noticeText = String(j['Notice Text'] || '').trim();
const errors = [];
if (!branches.includes(branch)) errors.push('Invalid or missing Branch');
if (!(yearLabel in yearMap)) errors.push('Invalid or missing Year');
if (!divisions.includes(division)) errors.push('Invalid or missing Division');
if (noticeText.length < 5) errors.push('Notice Text is missing or too short');
return { json: {
  branch, year_label: yearLabel, year_num: yearMap[yearLabel] || null, division,
  notice_text: noticeText,
  submitted_at: j.submittedAt || new Date().toISOString(),
  test_mode: false,
  live_send_authorized: true,
  valid: errors.length === 0,
  errors
} };

