const form = $('Validate Form Fields').item.json;
const keys = ['event_type','title','description','venue','branch','year','division','start_date','start_time','end_date','end_time','deadline','links','summary'];
const empty = {}; keys.forEach(k => empty[k] = null); empty.links = [];
let raw = '';
const j = $json;
if (j.error) raw = '';
else if (Array.isArray(j.content)) raw = (j.content.find(b => b.type === 'text') || {}).text || '';
else raw = j.text || j.output || '';
let ai = null, aiOk = false, aiError = j.error ? 'AI service error: ' + (j.error.message || JSON.stringify(j.error)).slice(0, 200) : null;
if (raw) {
  try {
    const cleaned = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/,'').trim();
    const p = JSON.parse(cleaned);
    if (p && typeof p === 'object' && !Array.isArray(p)) { ai = p; aiOk = true; }
    else aiError = 'AI response was not a JSON object';
  } catch (e) { aiError = 'AI response was not valid JSON'; }
} else if (!aiError) aiError = 'AI response was empty';
const clean = Object.assign({}, empty);
if (aiOk) keys.forEach(k => { if (ai[k] !== undefined) clean[k] = ai[k]; });
const dateOk = d => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d);
const timeOk = t => typeof t === 'string' && /^\d{2}:\d{2}$/.test(t);
if (!dateOk(clean.start_date)) clean.start_date = null;
if (!timeOk(clean.start_time)) clean.start_time = null;
if (!dateOk(clean.end_date)) clean.end_date = null;
if (!timeOk(clean.end_time)) clean.end_time = null;
if (!Array.isArray(clean.links)) clean.links = [];
// Faculty form selection always wins over AI for targeting
return { json: Object.assign({}, form, { ai_ok: aiOk, ai_error: aiError, extracted: clean }) };

const ctx = $('Parse AI Response').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const seen = new Set(); const recipients = []; const invalid = []; const mismatched = [];
for (const r of rows) {
  // Safety: never accept a row outside the selected Branch + Year + Division
  const okMatch = String(r.Branch).trim() === ctx.branch && Number(r.Year) === ctx.year_num && String(r.Division).trim().toUpperCase() === ctx.division;
  if (!okMatch) { mismatched.push(r.Roll_No || r.Email || 'unknown'); continue; }
  const email = String(r.Email || '').trim().toLowerCase();
  if (!emailRe.test(email)) { invalid.push({ roll_no: r.Roll_No || null, email: r.Email || null }); continue; }
  if (seen.has(email)) continue;
  seen.add(email);
  recipients.push({ roll_no: r.Roll_No, name: r.Name, email });
}
const raw = JSON.stringify([ctx.branch, ctx.year_num, ctx.division, ctx.notice_text]);
let h = 0; for (let i = 0; i < raw.length; i++) { h = ((h << 5) - h + raw.charCodeAt(i)) | 0; }
const hash = 'n' + Math.abs(h);
const sd = $getWorkflowStaticData('global');
const duplicate = !!(sd.sent && sd.sent[hash]);
return [{ json: Object.assign({}, ctx, { recipients, recipient_count: recipients.length, invalid_emails: invalid, mismatched_rows: mismatched, notice_hash: hash, duplicate_submission: duplicate }) }];

const ctx = $('Validate and Deduplicate Recipients').first().json;
const e = ctx.extracted || {};
const scheduled = !!(e.start_date && e.start_time);
let conflicts = [];
if (scheduled) {
  let evs = [];
  try { evs = $('Check Calendar Conflicts').all().map(i => i.json).filter(x => x && x.id); } catch (err) { evs = []; }
  conflicts = evs.filter(x => x.status !== 'cancelled').map(x => ({ id: x.id, summary: x.summary || '(no title)', start: x.start && (x.start.dateTime || x.start.date), end: x.end && (x.end.dateTime || x.end.date) }));
}
const endKnown = !!(e.end_time);
const sufficient = scheduled && !!e.title;
const can_create_event = sufficient && conflicts.length === 0 && !ctx.test_mode && !ctx.duplicate_submission;
const startISO = scheduled ? e.start_date + 'T' + e.start_time + ':00+05:30' : null;
const endDate = e.end_date || e.start_date;
let endISO = null;
if (scheduled) {
  if (endKnown) endISO = endDate + 'T' + e.end_time + ':00+05:30';
  else { const d = new Date(startISO); d.setHours(d.getHours() + 1); endISO = d.toISOString(); }
}
return [{ json: Object.assign({}, ctx, { scheduled, calendar_conflicts: conflicts, has_conflict: conflicts.length > 0, event_time_sufficient: sufficient, end_time_assumed: scheduled && !endKnown, can_create_event, event_start: startISO, event_end: endISO, timezone: 'Asia/Kolkata' }) }];

const c = $('Evaluate Calendar Result').first().json;
const e = c.extracted || {};
let created = null;
try { const ev = $('Create Calendar Event').all()[0]; created = ev && ev.json && ev.json.htmlLink ? ev.json.htmlLink : null; } catch (err) {}
const lines = [];
lines.push('Notice for ' + c.branch + ' ' + c.year_label + ' Division ' + c.division);
lines.push('');
if (e.title) lines.push(e.title);
lines.push(e.summary || c.notice_text);
if (e.venue) lines.push('Venue: ' + e.venue);
if (e.start_date) lines.push('Date: ' + e.start_date + (e.start_time ? ' at ' + e.start_time + ' IST' : ''));
if (e.deadline) lines.push('Deadline: ' + e.deadline);
if (Array.isArray(e.links) && e.links.length) lines.push('Links: ' + e.links.join(', '));
if (c.has_conflict) lines.push('Note: a calendar clash exists for this slot; please wait for confirmation.');
if (!c.ai_ok) { lines.length = 0; lines.push('Notice for ' + c.branch + ' ' + c.year_label + ' Division ' + c.division); lines.push(''); lines.push(c.notice_text); }
const body = lines.join('\n');
const subject = '[Campus Notice] ' + (e.title || (c.branch + ' ' + c.year_label + ' Div ' + c.division));
const html = body.split('\n').map(l => l ? '<p>' + l.replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</p>' : '').join('');
const eventMissing = !!c.scheduled && !created;
const send_allowed = !c.test_mode && c.live_send_authorized === true && !c.duplicate_submission && c.recipient_count > 0 && c.recipient_count <= 300 && c.ai_ok === true && !c.has_conflict && !eventMissing;
const blockReasons = [];
if (c.test_mode) blockReasons.push('test mode is ON');
if (c.live_send_authorized !== true) blockReasons.push('live sending not authorized');
if (c.duplicate_submission) blockReasons.push('duplicate submission');
if (c.recipient_count === 0) blockReasons.push('no matching students');
if (c.recipient_count > 300) blockReasons.push('recipient count exceeds safety cap of 300');
if (c.ai_ok !== true) blockReasons.push('AI extraction failed or unreliable');
if (c.has_conflict) blockReasons.push('calendar conflict needs resolution');
if (eventMissing) blockReasons.push('calendar event was not created');
return [{ json: Object.assign({}, c, { subject, message_text: body, message_html: html, calendar_event_link: created, send_allowed, block_reasons: blockReasons, preview: { recipients: c.recipients.map(r => r.email), recipient_count: c.recipient_count, subject, message: body } }) }];

const m = $('Generate Notification and Preview').first().json;
let results = [];
if (m.send_allowed) { try { results = $('Send Notification Email').all().map(i => i.json); } catch (err) { results = []; } }
const failures = results.filter(r => r.error).map(r => String(r.error.message || r.error).slice(0, 200));
const sentCount = m.send_allowed ? results.filter(r => !r.error).length : 0;
let status;
if (m.recipient_count === 0) status = 'no_matching_students';
else if (m.duplicate_submission) status = 'duplicate_blocked';
else if (!m.send_allowed) status = 'preview_only';
else status = failures.length ? 'sent_with_failures' : 'sent';
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {}; sd.log = sd.log || [];
const entry = { at: new Date().toISOString(), hash: m.notice_hash, status, recipients: m.recipient_count, sent: sentCount, failed: failures.length };
if (m.send_allowed && sentCount > 0) sd.sent[m.notice_hash] = entry.at;
sd.log.push(entry); if (sd.log.length > 50) sd.log.shift();
return [{ json: {
  status, test_mode: m.test_mode, send_blocked_because: m.block_reasons,
  recipient_count: m.recipient_count, recipients_preview: m.preview.recipients,
  invalid_emails: m.invalid_emails, sent_count: sentCount, failed_count: failures.length, failures,
  calendar_conflicts: m.calendar_conflicts, calendar_event_link: m.calendar_event_link,
  ai_ok: m.ai_ok, ai_error: m.ai_error, subject: m.subject, message_preview: m.message_text
} }];
